// Module 7 evidence: installs one real appliance from a package generated by the dev stack and lets it
// enroll with the dev API's agent gateway (which must listen on the host address: AGENT_GATEWAY_HOST=0.0.0.0,
// AGENT_GATEWAY_URL=https://<host address>:8443), then captures the enrolled deployment pages, the appliance's
// status, verify.sh (13/13), agent status and a certificate renewal; removes the appliance afterwards.
// Creates real (non-synthetic) records in the dev database; reseed afterwards. Usage: node scripts/screenshots-m6.mjs
import { spawnSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from '@playwright/test';

const base = process.env.BASE_URL ?? 'http://localhost:3210';
const outDir = fileURLToPath(new URL('../../../docs/reports/module-07/', import.meta.url));
const shots = `${outDir}screenshots/`;
mkdirSync(shots, { recursive: true });
const env = Object.fromEntries(
  readFileSync(new URL('../../api/.env', import.meta.url), 'utf8').split(/\r?\n/).filter((l) => /^[A-Z0-9_]+=/.test(l)).map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)]),
);
const sh = (cmd, timeout = 400_000) => {
  const r = spawnSync('wsl', ['--exec', 'bash', '-c', cmd], { encoding: 'utf8', timeout });
  return { code: r.status, out: (r.stdout ?? '').trim(), err: (r.stderr ?? '').trim() };
};

const browser = await chromium.launch({ channel: 'msedge' });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
const page = await ctx.newPage();
const login = await page.request.post(`${base}/api/v1/auth/login`, { data: { email: 'jordan.ops@psacc.test', password: env.SEED_DEFAULT_PASSWORD }, headers: { origin: base } });
if (login.status() !== 200) throw new Error(`login ${login.status()}`);
const csrf = async () => ({ origin: base, 'x-csrf-token': (await ctx.cookies()).find((c) => c.name === 'psacc_csrf').value });
const api = async (method, path, data) => {
  const r = await page.request.fetch(`${base}/api/v1${path}`, { method, data, headers: await csrf() });
  if (!r.ok()) throw new Error(`${method} ${path} → ${r.status()} ${await r.text()}`);
  return (r.headers()['content-type'] ?? '').includes('json') ? r.json() : r.body();
};
const shot = async (p, name, full = true) => {
  await p.evaluate(() => window.scrollTo(0, 0));
  await p.addStyleTag({ content: 'nextjs-portal { display: none !important; }' }).catch(() => undefined);
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${shots}${name}.png`, fullPage: full });
  console.log('saved', name);
};

// 1. A real package from the dev Control Plane.
const inst = (await api('GET', '/psa-instances?provider=autotask&status=active&pageSize=50')).items.find((i) => i.client.code !== 'CL-00001' && i.enabledServiceCount > 0);
const dep = await api('POST', '/deployments', { clientId: inst.client.id, psaInstanceId: inst.id, targetEnvironment: 'local_test', targetOs: 'linux', targetArch: 'amd64', hostLabel: 'module7-demo' });
const pkg = (await api('POST', `/deployments/${dep.id}/packages`, { tokenValidityHours: 4 })).currentPackage;
const zip = await api('POST', `/deployments/${dep.id}/packages/${pkg.id}/download`);
const winTmp = realpathSync.native(mkdtempSync(join(tmpdir(), 'psacc-m7-')));
writeFileSync(join(winTmp, pkg.fileName), zip);
const project = `psacc-${dep.code.toLowerCase()}`;
const work = `/tmp/psacc-m7shots/${project}`;
const port = 18000 + (Number(dep.code.replace(/\D/g, '')) % 1000);
const unixZip = sh(`wslpath -a '${join(winTmp, pkg.fileName)}'`).out;

try {
  // 2. Install with the package's own script (development profile, locally built image).
  let r = sh(`rm -rf /tmp/psacc-m7shots && mkdir -p /tmp/psacc-m7shots && cd /tmp/psacc-m7shots && unzip -q "${unixZip}" && cd ${project} && cp config/edge.env.template .env && echo EDGE_BACKUP_INITIAL_DELAY_SECONDS=3 >> .env && scripts/install.sh`);
  if (r.code !== 0) throw new Error(`install failed: ${r.err || r.out}`);
  writeFileSync(`${outDir}install-output.txt`, `$ scripts/install.sh\n${r.out}\n`);
  for (let i = 0; i < 75 && !sh(`cd ${work} && docker compose ps --format '{{.Service}} {{.Health}}'`).out.includes('edge-api healthy'); i++) sh('sleep 2');
  sh('sleep 6'); // first backup + first agent report

  // 3. Wait for the agent to enroll with the Control Plane over the gateway.
  let d;
  for (let n = 0; n < 60; n++) {
    d = await api('GET', `/deployments/${dep.id}`);
    if (d.lifecycleState === 'enrolled') break;
    sh('sleep 2');
  }
  if (d.lifecycleState !== 'enrolled') throw new Error('agent did not enroll — is the dev gateway on the host address?');
  sh('sleep 20'); // at least one heartbeat after enrollment

  // 4. Control Plane pages for the enrolled deployment.
  await page.goto(`${base}/deployments/${dep.id}`, { waitUntil: 'networkidle' });
  await shot(page, '01-deployment-enrolled');
  await page.goto(`${base}/deployments/${dep.id}/installation`, { waitUntil: 'networkidle' });
  await shot(page, '02-installation-package-consumed');
  await page.goto(`${base}/deployments?lifecycle=enrolled`, { waitUntil: 'networkidle' });
  await shot(page, '03-deployments-enrolled-filter', false);

  // 5. Appliance side: local status, verify.sh, agent status, renewal.
  const local = `http://127.0.0.1:${port}`;
  const ui = await ctx.newPage();
  await ui.goto(`${local}/`);
  const password = `demo-${randomBytes(9).toString('base64url')}`;
  await ui.fill('#username', 'localadmin');
  await ui.fill('#password', password);
  await ui.fill('#confirm', password);
  await ui.click('button[type=submit]');
  await ui.waitForURL(/\/credentials/);
  await ui.goto(`${local}/`);
  await shot(ui, '04-appliance-status-enrolled');
  r = sh(`cd ${work} && scripts/verify.sh`, 120_000);
  writeFileSync(`${outDir}verify-output.txt`, `$ scripts/verify.sh   (exit ${r.code})\n${r.out}\n`);
  r = sh(`cd ${work} && docker compose -f compose.yaml exec -T edge-agent edge-agent status`);
  writeFileSync(`${outDir}agent-status.txt`, `$ docker compose exec edge-agent edge-agent status\n${r.out}\n`);
  r = sh(`cd ${work} && docker compose -f compose.yaml exec -T edge-agent edge-agent renew`);
  writeFileSync(`${outDir}agent-renew.txt`, `$ docker compose exec edge-agent edge-agent renew   (exit ${r.code})\n${r.out}\n`);
  r = sh(`cd ${work} && docker compose -f compose.yaml logs --no-log-prefix edge-agent | grep -E 'enrolled|renewed|agent started' | head -5`);
  writeFileSync(`${outDir}agent-log-excerpt.txt`, `$ docker compose logs edge-agent (enrollment and renewal lines)\n${r.out}\n`);
  await page.goto(`${base}/deployments/${dep.id}`, { waitUntil: 'networkidle' });
  await shot(page, '05-deployment-after-renewal');} finally {
  sh(`cd ${work} && docker compose -f compose.yaml down --volumes --remove-orphans; rm -rf /tmp/psacc-m7shots`);
  rmSync(winTmp, { recursive: true, force: true });
  await browser.close();
}
